// F4-only reference controller. Demo data never reaches the real product.
const params=new URLSearchParams(location.search);
const direction={key:'slate'},variant={variant:'f4'},isMono=true,isApple=false;
const thumbnail=params.has('thumbnail');
document.body.className='theme-slate slate-variant-f4'+(thumbnail?' thumbnail':'');
const app=document.querySelector('#prototype');
const statusLabels=['待開始','進行中','待確認','已完成'];
let tasks=structuredClone(DEMO_TASKS),query='',onlyMine=false,week=false,view='board';
const storageKey='igotthis-f4-reference-v1';
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(!thumbnail&&Array.isArray(saved)&&saved.length&&saved.every(t=>t.id&&t.title&&Number.isInteger(t.status)&&t.status>=0&&t.status<4))tasks=saved;}catch{}
function render(){renderMono()}
function renderTasks(){renderMonoTasks()}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const avatar=(person,extra='')=>`<span class="avatar avatar-${['林','陳','許','吳'].indexOf(person)} ${extra}" aria-label="${esc(person)}">${esc(person)}</span>`;
function notify(text){const n=document.querySelector('#feedback');n.textContent=text;n.classList.add('visible');clearTimeout(window.feedbackTimer);window.feedbackTimer=setTimeout(()=>n.classList.remove('visible'),2200)}
function persist(){if(thumbnail)return;try{localStorage.setItem(storageKey,JSON.stringify(tasks))}catch{notify('本次修改已套用，瀏覽器未開放持久儲存。')}}
function percentage(){return Math.round(tasks.filter(t=>t.status===3).length/tasks.length*100)||0}
function filtered(){return tasks.filter(t=>(!onlyMine||t.person==='林')&&(!week||(t.due<='10/16'&&t.status!==3))&&(`${t.title} ${t.id} ${t.label} ${t.name}`.toLowerCase().includes(query.toLowerCase().trim())))}
function dialog(content,label){const d=document.querySelector('#task-dialog');d.innerHTML=content;d.setAttribute('aria-label',label);if(!d.open)d.showModal();d.querySelector('input,select,button')?.focus();}
function closeDialog(){document.querySelector('#task-dialog').close();}
function openTask(id){const t=tasks.find(t=>t.id===id);if(!t)return;dialog(`<form id="detail-form" data-id="${esc(t.id)}"><div class="dialog-heading"><span>${esc(t.id)} <span class="task-tag">${esc(t.label)}</span></span><button type="button" class="icon-button" data-action="close" aria-label="關閉任務">${icon('close')}</button></div><h2>${esc(t.title)}</h2><p class="dialog-description">${esc(t.note)}</p><div class="form-grid"><label>目前狀態<select name="status" aria-label="目前狀態">${statusLabels.map((s,i)=>`<option value="${i}" ${i===t.status?'selected':''}>${s}</option>`).join('')}</select></label><label>優先程度<select name="priority" aria-label="優先程度">${['高','中','低'].map(s=>`<option ${s===t.priority?'selected':''}>${s}</option>`).join('')}</select></label></div><div class="detail-meta"><span>負責人</span><b>${avatar(t.person)}${esc(t.name)}</b><span>到期日</span><b>2026/${esc(t.due)}</b></div><div class="detail-note">${icon('chat')}此為示範任務，變更只儲存在你的瀏覽器。</div><footer class="dialog-actions"><button type="button" class="secondary-button" data-action="close">取消</button><button class="primary-button" type="submit">儲存變更</button></footer></form>`,'任務詳情')}
function newTask(status=0){dialog(`<form id="new-form"><div class="dialog-heading"><span>網站改版計畫</span><button type="button" class="icon-button" data-action="close" aria-label="關閉新增任務">${icon('close')}</button></div><h2>新增任務</h2><label class="form-field">任務名稱<input name="title" required maxlength="80" placeholder="下一件要完成的事…" autocomplete="off"></label><label class="form-field">任務說明<textarea name="note" rows="3" maxlength="500" placeholder="補充這項任務的目標與細節"></textarea></label><div class="form-grid"><label>目前狀態<select name="status" aria-label="目前狀態">${statusLabels.map((s,i)=>`<option value="${i}" ${i===status?'selected':''}>${s}</option>`).join('')}</select></label><label>到期日<input name="due" type="date" required value="2026-10-16" min="2026-10-01" max="2026-10-31"></label></div><div class="detail-note">新任務會指派給你，僅保留在此瀏覽器。</div><footer class="dialog-actions"><button type="button" class="secondary-button" data-action="close">取消</button><button class="primary-button" type="submit">新增任務</button></footer></form>`,'新增任務');document.querySelector('[name="title"]').focus()}
function activity(){dialog(`<div class="dialog-heading"><span>團隊動態</span><button class="icon-button" data-action="close" aria-label="關閉團隊動態">${icon('close')}</button></div><h2>每個進展，都值得看見。</h2><div class="activity-entry">${avatar('吳')}<div><b>佳穎更新了本週工作重點</b><p>先對齊元件和首頁資訊架構。</p><small>今天 09:30</small></div></div><div class="activity-entry">${avatar('陳')}<div><b>沛庭提交了產品文案</b><p>確認產品文案與語氣 → 待確認</p><small>昨天 16:40</small></div></div><div class="activity-entry">${avatar('林')}<div><b>以安完成了團隊訪談</b><p>已整理主要需求與工作流程。</p><small>10 月 12 日</small></div></div><p class="dialog-description">此為示範動態，未連接真實團隊資料。</p>`,'團隊動態')}
function resetPrompt(){dialog(`<div class="dialog-heading"><span>重設示範資料</span><button class="icon-button" data-action="close" aria-label="關閉">${icon('close')}</button></div><h2>回到最初的 8 項任務？</h2><p class="dialog-description">此提案中新增的任務與狀態修改將會清除，收藏與其他提案不受影響。</p><div class="dialog-actions"><button class="secondary-button" data-action="close">保留修改</button><button class="primary-button" data-action="confirm-reset">重設此提案</button></div>`,'重設示範資料')}
app.addEventListener('input',e=>{if(e.target.id==='task-search'){query=e.target.value;renderTasks()}});
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.task)return openTask(b.dataset.task);if(b.hasAttribute('data-new-status'))return newTask(Number(b.dataset.newStatus));if(b.dataset.view){view=b.dataset.view;render();return;}switch(b.dataset.action){case 'new':newTask();break;case 'close':closeDialog();break;case 'mine':onlyMine=!onlyMine;render();break;case 'week':week=!week;render();break;case 'all':case 'clear-search':query='';onlyMine=false;week=false;render();break;case 'activity':activity();break;case 'reset':resetPrompt();break;case 'confirm-reset':tasks=structuredClone(DEMO_TASKS);query='';onlyMine=false;week=false;persist();closeDialog();render();notify('已重設示範資料');break;}});
document.addEventListener('submit',e=>{if(!['detail-form','new-form'].includes(e.target.id))return;e.preventDefault();const data=new FormData(e.target);if(e.target.id==='detail-form'){const t=tasks.find(t=>t.id===e.target.dataset.id);t.status=Number(data.get('status'));t.priority=data.get('priority');closeDialog();persist();render();notify('已儲存任務變更');}else{const title=data.get('title').trim();if(!title){const input=e.target.querySelector('[name="title"]');input.setCustomValidity('請輸入任務名稱。');input.reportValidity();input.addEventListener('input',()=>input.setCustomValidity(''),{once:true});return;}tasks.push({id:`WEB-${Math.max(...tasks.map(t=>Number(t.id.split('-')[1])))+1}`,title,note:data.get('note').trim()||'尚未加入任務說明。',status:Number(data.get('status')),priority:'中',person:'林',name:'林以安',label:'企劃',due:data.get('due').slice(5).replace('-','/')});query='';week=false;closeDialog();persist();render();notify('已新增任務');}});
render();
